// Companies' public job boards. ats = greenhouse | lever | ashby
// token = the company slug: boards.greenhouse.io/<token> | jobs.lever.co/<token> | jobs.ashbyhq.com/<token>
// Candidates: keep the ones that return jobs after the first run, delete the rest.
const boards = [
  // already verified
  { ats: 'greenhouse', token: 'intercom' },
  { ats: 'greenhouse', token: 'stripe' },
  { ats: 'greenhouse', token: 'datadog' },
  { ats: 'greenhouse', token: 'squarespace' },
  // candidates: Irish-hiring tech
  { ats: 'greenhouse', token: 'hubspot' },
  { ats: 'greenhouse', token: 'zendesk' },
  { ats: 'greenhouse', token: 'okta' },
  { ats: 'greenhouse', token: 'dropbox' },
  { ats: 'greenhouse', token: 'mongodb' },
  { ats: 'greenhouse', token: 'toast' },
  { ats: 'greenhouse', token: 'workhuman' },
  { ats: 'greenhouse', token: 'fenergo' },
  { ats: 'greenhouse', token: 'wayflyer' },
  { ats: 'ashby',      token: 'tines' },
  { ats: 'ashby',      token: 'wayflyer' },
  { ats: 'lever',      token: 'flipdish' },
];
const url = b => ({
  greenhouse: `https://boards-api.greenhouse.io/v1/boards/${b.token}/jobs`,
  lever: `https://api.lever.co/v0/postings/${b.token}?mode=json`,
  ashby: `https://api.ashbyhq.com/posting-api/job-board/${b.token}`,
}[b.ats]);
return boards.map(b => ({ json: { ...b, api_url: url(b) } }));

const LOC = /(ireland|dublin|galway|cork|limerick|athlone|remote[^a-z]*(ie|ireland|emea|europe))/i;
const ROLE = /(business analyst|data analyst|product analyst|bi analyst|business intelligence|analytics|reporting analyst|insights analyst|associate product manager|product manager|product owner|operations analyst|graduate|intern)/i;
const SENIOR = /(senior|\bsr\.?\b|lead|principal|staff|director|head of|\bvp\b|\bii\b|\biii\b|manager ii)/i;
const keep = (title, loc) => ROLE.test(title || '') && !SENIOR.test(title || '') && LOC.test(loc || '');
const clean = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const hash = s => { let h = 5381; for (const c of String(s)) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(36); };

const boards = $('ATS Boards').all();
const out = [];
$input.all().forEach((item, i) => {
  const b = boards[i]?.json || {};
  const d = item.json;
  let rows = [];
  if (b.ats === 'greenhouse') rows = (d.jobs || []).map(j => ({ id: j.id, title: j.title, loc: j.location?.name, url: j.absolute_url, posted: j.updated_at,
      detail: `https://boards-api.greenhouse.io/v1/boards/${b.token}/jobs/${j.id}` }));
  if (b.ats === 'lever') rows = (Array.isArray(d) ? d : (d.data || [])).map(j => ({ id: j.id, title: j.text, loc: [j.categories?.location, ...(j.categories?.allLocations || [])].join(' '), url: j.hostedUrl,
      posted: j.createdAt ? new Date(j.createdAt).toISOString() : '', snippet: clean(j.descriptionPlain || j.description).slice(0, 1500) }));
  if (b.ats === 'ashby') rows = (d.jobs || []).map(j => ({ id: j.id, title: j.title, loc: [j.location, j.isRemote ? 'remote' : '', ...(j.secondaryLocations || []).map(s => s.location)].join(' '), url: j.jobUrl,
      posted: j.publishedAt || '', snippet: clean(j.descriptionPlain || j.descriptionHtml).slice(0, 1500) }));
  for (const r of rows) {
    if (!keep(r.title, r.loc)) continue;
    out.push({ json: { job_id: `${b.ats.slice(0, 2)}-${b.token}-${r.id}`, source: b.ats, company: b.token, title: r.title, location: clean(r.loc),
      url: r.url, posted_at: r.posted || '', description_snippet: r.snippet || '', detail_api_url: r.detail || '', found_at: $now.toISO(), status: 'new' } });
  }
});
return out;

