const hash = s => { let h = 5381; for (const c of String(s)) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(36); };

const out = [];
for (const item of $input.all()) {
  for (const j of (item.json.jobs_results || [])) {
    if (!keep(j.title, j.location || '')) continue;
    const apply = (j.apply_options || [])[0] || {};
    out.push({ json: {
      job_id: `gj-${hash((j.company_name || '') + '|' + (j.title || '') + '|' + (j.location || ''))}`,
      source: `google_jobs${j.via ? ' (' + String(j.via).replace(/^via\s+/i, '') + ')' : ''}`,
      company: j.company_name || '', title: j.title, location: j.location || '',
      url: apply.link || j.share_link || '', posted_at: j.detected_extensions?.posted_at || '',
      description_snippet: clean(j.description).slice(0, 1500), detail_api_url: '', found_at: $now.toISO(), status: 'new' } });
  }
}
return out;

// Dedupe against the SHEET (visible, can't drift): a job is new only if its id AND company|title are not already in JobsData
const existing = $input.all().map(i => i.json).filter(r => r.job_id);
const ids = new Set(existing.map(r => String(r.job_id)));
const keys = new Set(existing.map(r => `${String(r.company).toLowerCase().trim()}|${String(r.title).toLowerCase().trim()}`));
return $('Dedupe This Batch1').all().filter(i => {
  const k = `${String(i.json.company).toLowerCase().trim()}|${String(i.json.title).toLowerCase().trim()}`;
  return !ids.has(String(i.json.job_id)) && !keys.has(k);
});

