// Title Filter: one gate for every source. BA / DA / PM-type roles only.
const CORE = /(business analyst|data analyst|product analyst|bi analyst|business intelligence|reporting analyst|insights analyst|analytics|operations analyst|process analyst|systems analyst|product manager|product owner|associate product|\banalyst\b)/i;
const BLOCK = /(engineer|developer|teacher|professor|lecturer|nurse|doctor|pharmacist|mechanical|electrical|civil|chef|driver|sales executive|recruiter|solicitor|senior|\bsr\.?\b|\blead\b|principal|\bstaff\b|director|head of|\bvp\b|\bii\b|\biii\b|summer 20\d\d)/i;
return $input.all().filter(i => {
  const t = String(i.json.title || '');
  return CORE.test(t) && !BLOCK.test(t);
});

